# -------------------------- exceptions --------------------------
class CliError(Exception):
    pass
class InvalidData(CliError):
    pass
class HexError(CliError):
    def __init__(self, msg: str):
        self.msg = msg
        super().__init__(msg)
class UintParseError(CliError):
    def __init__(self, kind: str):
        self.kind = kind
        super().__init__(kind)

# -------------------------- keccak-256 --------------------------
# Compact, original implementation of Keccak-f[1600] with Keccak padding (0x01).
ROT = [
     0,  1, 62, 28, 27,
    36, 44,  6, 55, 20,
     3, 10, 43, 25, 39,
    41, 45, 15, 21,  8,
    18,  2, 61, 56, 14,
]
RC = [
    0x0000000000000001, 0x0000000000008082,
    0x800000000000808a, 0x8000000080008000,
    0x000000000000808b, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009,
    0x000000000000008a, 0x0000000000000088,
    0x0000000080008009, 0x000000008000000a,
    0x000000008000808b, 0x800000000000008b,
    0x8000000000008089, 0x8000000000008003,
    0x8000000000008002, 0x8000000000000080,
    0x000000000000800a, 0x800000008000000a,
    0x8000000080008081, 0x8000000000008080,
    0x0000000080000001, 0x8000000080008008,
]
MASK64 = (1 << 64) - 1

def rol(x, n):
    n %= 64
    return ((x << n) | (x >> (64 - n))) & MASK64

def keccak_f(st):
    # state indexed x + 5*y
    for rc in RC:
        # theta
        c = [st[x] ^ st[x+5] ^ st[x+10] ^ st[x+15] ^ st[x+20] for x in range(5)]
        d = [c[(x-1) % 5] ^ rol(c[(x+1) % 5], 1) for x in range(5)]
        for x in range(5):
            for y in range(5):
                st[x + 5*y] ^= d[x]
        # rho/pi
        b = [0] * 25
        for x in range(5):
            for y in range(5):
                src = x + 5*y
                nx = y
                ny = (2*x + 3*y) % 5
                b[nx + 5*ny] = rol(st[src], ROT[src])
        # chi
        for x in range(5):
            for y in range(5):
                st[x + 5*y] = b[x + 5*y] ^ ((~b[((x+1) % 5) + 5*y]) & b[((x+2) % 5) + 5*y])
                st[x + 5*y] &= MASK64
        # iota
        st[0] ^= rc

def keccak256(data: bytes) -> bytes:
    rate = 136
    st = [0] * 25
    off = 0
    while off + rate <= len(data):
        block = data[off:off+rate]
        for i in range(rate // 8):
            st[i] ^= int.from_bytes(block[8*i:8*i+8], 'little')
        keccak_f(st)
        off += rate
    rem = bytearray(data[off:])
    rem.append(0x01)
    if len(rem) < rate:
        rem += b'\x00' * (rate - len(rem))
    rem[-1] ^= 0x80
    for i in range(rate // 8):
        st[i] ^= int.from_bytes(rem[8*i:8*i+8], 'little')
    keccak_f(st)
    out = bytearray()
    while len(out) < 32:
        for i in range(rate // 8):
            out += st[i].to_bytes(8, 'little')
            if len(out) >= 32:
                return bytes(out[:32])
        keccak_f(st)
    return bytes(out[:32])

# -------------------------- ABI types --------------------------
@dataclass(frozen=True)
class AbiType:
    kind: str
    bits: Optional[int] = None
    size: Optional[int] = None
    elem: Optional['AbiType'] = None
    length: Optional[int] = None
    components: Optional[Tuple['AbiType', ...]] = None

    def canonical(self) -> str:
        k = self.kind
        if k == 'uint': return f"uint{self.bits or 256}"
        if k == 'int': return f"int{self.bits or 256}"
        if k == 'bool': return 'bool'
        if k == 'address': return 'address'
        if k == 'string': return 'string'
        if k == 'bytes': return 'bytes'
        if k == 'fixed_bytes': return f"bytes{self.size}"
        if k == 'array':
            return self.elem.canonical() + ('[]' if self.length is None else f'[{self.length}]')
        if k == 'tuple':
            return '(' + ','.join(c.canonical() for c in (self.components or ())) + ')'
        return k

    def is_dynamic(self) -> bool:
        if self.kind in ('string', 'bytes'):
            return True
        if self.kind == 'array':
            return self.length is None or self.elem.is_dynamic()
        if self.kind == 'tuple':
            return any(c.is_dynamic() for c in (self.components or ()))
        return False

    def static_size_words(self) -> int:
        if self.is_dynamic():
            return 1
        if self.kind == 'array':
            return (self.length or 0) * self.elem.static_size_words()
        if self.kind == 'tuple':
            return sum(c.static_size_words() for c in (self.components or ()))
        if self.kind == 'fixed_bytes' and self.size == 0:
            # ethabi accepts bytes0 as a zero-sized fixed byte token.
            return 0
        return 1

def parse_type(s: str) -> AbiType:
    if s is None:
        raise InvalidData()
    # peel array suffixes from right to left
    base = s
    suffixes = []
    while base.endswith(']'):
        i = base.rfind('[')
        if i < 0:
            raise InvalidData()
        inside = base[i+1:-1]
        if inside == '':
            suffixes.append(None)
        else:
            if not inside.isdigit():
                raise InvalidData()
            suffixes.append(int(inside))
        base = base[:i]
    if base == 'address': t = AbiType('address')
    elif base == 'bool': t = AbiType('bool')
    elif base == 'string': t = AbiType('string')
    elif base == 'bytes': t = AbiType('bytes')
    elif re.fullmatch(r'bytes\d+', base):
        t = AbiType('fixed_bytes', size=int(base[5:]))
    elif base == 'uint':
        t = AbiType('uint', bits=256)
    elif base == 'int':
        t = AbiType('int', bits=256)
    elif re.fullmatch(r'uint\d+', base):
        t = AbiType('uint', bits=int(base[4:]))
    elif re.fullmatch(r'int\d+', base):
        t = AbiType('int', bits=int(base[3:]))
    else:
        raise InvalidData()
    for ln in reversed(suffixes):
        t = AbiType('array', elem=t, length=ln)
    return t

def type_from_abi_param(p: dict) -> AbiType:
    if p.get('type') == 'tuple':
        comps = tuple(type_from_abi_param(c) for c in p.get('components', []) or [])
        t = AbiType('tuple', components=comps)
        # tuple arrays are represented as type "tuple[]" or "tuple[2]"
        typ = p.get('type', 'tuple')
        suffix = typ[5:]
        while suffix:
            if not suffix.startswith('['): break
            j = suffix.find(']')
            inside = suffix[1:j]
            ln = None if inside == '' else int(inside)
            t = AbiType('array', elem=t, length=ln)
            suffix = suffix[j+1:]
        return t
    return parse_type(p.get('type'))

# -------------------------- hex and words --------------------------
def strip_0x_lower(s: str) -> str:
    return s[2:] if s.startswith('0x') else s

def parse_hex_bytes(s: str, allow_0x: bool=False) -> bytes:
    hs = strip_0x_lower(s) if allow_0x else s
    if len(hs) % 2:
        raise HexError('Odd number of digits')
    for i, ch in enumerate(hs):
        if ch not in '0123456789abcdefABCDEF':
            # Match the hex crate's position after optional lowercase 0x removal.
            raise HexError(f"Invalid character '{ch}' at position {i}")
    return bytes.fromhex(hs)

def word_from_int(n: int) -> bytes:
    n %= 1 << 256
    return n.to_bytes(32, 'big')

def int_from_word(w: bytes) -> int:
    return int.from_bytes(w[:32], 'big')

def pad32(b: bytes) -> bytes:
    return b + b'\x00' * ((32 - len(b) % 32) % 32)

def take_word(data: bytes, pos: int) -> bytes:
    if pos < 0 or pos + 32 > len(data):
        raise InvalidData()
    return data[pos:pos+32]

# -------------------------- value parsing --------------------------
def parse_uint_decimal(s: str) -> int:
    if not s or any(ch < '0' or ch > '9' for ch in s):
        raise UintParseError('InvalidCharacter')
    # U256 parser rejects values >= 2**256.
    n = int(s, 10)
    if n >= (1 << 256):
        raise UintParseError('InvalidLength')
    return n

def parse_int_decimal_twos(s: str) -> int:
    if s.startswith('-'):
        mag = parse_uint_decimal(s[1:])
        return (-mag) % (1 << 256)
    return parse_uint_decimal(s)

def split_array_items(s: str) -> List[str]:
    if not (s.startswith('[') and s.endswith(']')):
        raise InvalidData()
    body = s[1:-1]
    if body == '':
        return []
    items = []
    depth = 0
    start = 0
    for i, ch in enumerate(body):
        if ch in '[(':
            depth += 1
        elif ch in '])':
            depth -= 1
        elif ch == ',' and depth == 0:
            items.append(body[start:i])
            start = i + 1
    items.append(body[start:])
    return items

def parse_value(t: AbiType, s: str, lenient: bool=False) -> Any:
    k = t.kind
    if k == 'bool':
        if s == 'true' or s == '1': return True
        if s == 'false' or s == '0': return False
        raise InvalidData()
    if k == 'address':
        b = parse_hex_bytes(s, allow_0x=True)
        if len(b) != 20: raise InvalidData()
        return b
    if k == 'uint':
        if lenient:
            return parse_uint_decimal(s)
        b = parse_hex_bytes(s, allow_0x=False)
        if len(b) != 32: raise InvalidData()
        return int.from_bytes(b, 'big')
    if k == 'int':
        if lenient:
            return parse_int_decimal_twos(s)
        b = parse_hex_bytes(s, allow_0x=False)
        if len(b) != 32: raise InvalidData()
        return int.from_bytes(b, 'big')
    if k == 'string':
        return s.encode('utf-8')
    if k == 'bytes':
        return parse_hex_bytes(s, allow_0x=True)
    if k == 'fixed_bytes':
        b = parse_hex_bytes(s, allow_0x=True)
        if len(b) != (t.size or 0): raise InvalidData()
        return b
    if k == 'array':
        arr = [parse_value(t.elem, item, lenient) for item in split_array_items(s)]
        if t.length is not None and len(arr) != t.length:
            raise InvalidData()
        return arr
    if k == 'tuple':
        # Accept tuple values as [a,b] or (a,b), mainly for completeness.
        if s.startswith('(') and s.endswith(')'):
            ss = '[' + s[1:-1] + ']'
        else:
            ss = s
        items = split_array_items(ss)
        comps = list(t.components or ())
        if len(items) != len(comps): raise InvalidData()
        return tuple(parse_value(ct, item, lenient) for ct, item in zip(comps, items))
    raise InvalidData()

# -------------------------- ABI encoding --------------------------
def encode_primitive(t: AbiType, v: Any) -> bytes:
    k = t.kind
    if k in ('uint', 'int'):
        return word_from_int(int(v))
    if k == 'bool':
        return word_from_int(1 if v else 0)
    if k == 'address':
        return b'\x00' * 12 + bytes(v)
    if k == 'fixed_bytes':
        b = bytes(v)
        if t.size == 0:
            return b''
        return b + b'\x00' * (32 - len(b))
    raise InvalidData()

def encode_tuple(types: List[AbiType], vals: List[Any]) -> bytes:
    head_size = 0
    for t in types:
        head_size += 32 if t.is_dynamic() else 32 * t.static_size_words()
    heads = []
    tails = []
    tail_len = 0
    for t, v in zip(types, vals):
        if t.is_dynamic():
            enc = encode_value(t, v)
            heads.append(word_from_int(head_size + tail_len))
            tails.append(enc)
            tail_len += len(enc)
        else:
            heads.append(encode_value(t, v))
    return b''.join(heads) + b''.join(tails)

def encode_value(t: AbiType, v: Any) -> bytes:
    k = t.kind
    if k in ('uint', 'int', 'bool', 'address', 'fixed_bytes'):
        return encode_primitive(t, v)
    if k == 'string':
        b = bytes(v)
        return word_from_int(len(b)) + pad32(b)
    if k == 'bytes':
        b = bytes(v)
        return word_from_int(len(b)) + pad32(b)
    if k == 'array':
        arr = list(v)
        if t.length is not None and len(arr) != t.length:
            raise InvalidData()
        body = encode_tuple([t.elem] * len(arr), arr)
        if t.length is None:
            return word_from_int(len(arr)) + body
        else:
            return body
    if k == 'tuple':
        comps = list(t.components or ())
        vals = list(v)
        return encode_tuple(comps, vals)
    raise InvalidData()

def encode_params(types: List[AbiType], vals: List[Any]) -> bytes:
    return encode_tuple(types, vals)

# -------------------------- ABI decoding --------------------------
def decode_tuple(types: List[AbiType], data: bytes, base: int=0) -> List[Any]:
    values = []
    pos = base
    for t in types:
        if t.is_dynamic():
            off = int_from_word(take_word(data, pos))
            values.append(decode_value(t, data, base + off))
            pos += 32
        else:
            values.append(decode_value(t, data, pos))
            pos += 32 * t.static_size_words()
    return values

def decode_value(t: AbiType, data: bytes, pos: int) -> Any:
    k = t.kind
    if k == 'uint' or k == 'int':
        return int_from_word(take_word(data, pos))
    if k == 'bool':
        w = take_word(data, pos)
        if any(w[:-1]):
            raise InvalidData()
        return w[-1] == 1
    if k == 'address':
        return take_word(data, pos)[12:32]
    if k == 'fixed_bytes':
        if t.size == 0:
            return b''
        w = take_word(data, pos)
        return w[:t.size]
    if k == 'string':
        ln = int_from_word(take_word(data, pos))
        start = pos + 32
        end = start + ln
        if end > len(data): raise InvalidData()
        return data[start:end]
    if k == 'bytes':
        ln = int_from_word(take_word(data, pos))
        start = pos + 32
        end = start + ln
        if end > len(data): raise InvalidData()
        return data[start:end]
    if k == 'array':
        if t.length is None:
            ln = int_from_word(take_word(data, pos))
            return decode_tuple([t.elem] * ln, data, pos + 32)
        else:
            return decode_tuple([t.elem] * t.length, data, pos)
    if k == 'tuple':
        return tuple(decode_tuple(list(t.components or ()), data, pos))
    raise InvalidData()

# -------------------------- display --------------------------
def int_hex(n: int) -> str:
    if n == 0: return '0'
    return format(n, 'x')

def display_value(t: AbiType, v: Any) -> str:
    k = t.kind
    if k == 'bool': return 'true' if v else 'false'
    if k == 'address': return bytes(v).hex()
    if k in ('uint', 'int'): return int_hex(int(v))
    if k == 'bytes' or k == 'fixed_bytes': return bytes(v).hex()
    if k == 'string':
        try:
            return bytes(v).decode('utf-8')
        except UnicodeDecodeError:
            return bytes(v).decode('utf-8', 'replace')
    if k == 'array':
        return '[' + ','.join(display_value(t.elem, x) for x in v) + ']'
    if k == 'tuple':
        comps = list(t.components or ())
        return '(' + ','.join(display_value(ct, x) for ct, x in zip(comps, v)) + ')'
    return str(v)

def decode_hex_arg(data_arg: str) -> bytes:
    return parse_hex_bytes(data_arg, allow_0x=False)

# -------------------------- ABI JSON lookup --------------------------
def load_abi(path: str) -> list:
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def func_inputs(f):
    return [type_from_abi_param(p) for p in (f.get('inputs') or [])]

def func_outputs(f):
    return [type_from_abi_param(p) for p in (f.get('outputs') or [])]

def function_full_signature(f) -> str:
    ins = ','.join(t.canonical() for t in func_inputs(f))
    outs_types = func_outputs(f)
    s = f"{f.get('name','')}({ins})"
    if len(outs_types) > 0:
        s += ':(' + ','.join(t.canonical() for t in outs_types) + ')'
    return s

def function_selector(f) -> bytes:
    ins = ','.join(t.canonical() for t in func_inputs(f))
    sig = f"{f.get('name','')}({ins})".encode('utf-8')
    return keccak256(sig)[:4]

def name_part(query: str) -> str:
    return query.split('(', 1)[0] if '(' in query else query

def select_function(abi: list, query: str) -> dict:
    funcs = [x for x in abi if x.get('type') == 'function']
    if '(' in query:
        nm = name_part(query)
        named = [f for f in funcs if f.get('name') == nm]
        if not named:
            raise CliError(f"Invalid name: {nm}")
        matches = [f for f in named if function_full_signature(f) == query]
        if len(matches) == 1:
            return matches[0]
        raise CliError(f"invalid function signature `{query}`")
    named = [f for f in funcs if f.get('name') == query]
    if not named:
        raise CliError(f"Invalid name: {query}")
    if len(named) > 1:
        raise CliError(f"More than one function found for name `{query}`, try providing the full signature")
    return named[0]

def event_inputs(e):
    return [type_from_abi_param(p) for p in (e.get('inputs') or [])]

def event_signature(e) -> str:
    return f"{e.get('name','')}(" + ','.join(t.canonical() for t in event_inputs(e)) + ')'

def event_topic0(e) -> bytes:
    return keccak256(event_signature(e).encode('utf-8'))

def select_event(abi: list, query: str) -> dict:
    evs = [x for x in abi if x.get('type') == 'event']
    if '(' in query:
        nm = name_part(query)
        named = [e for e in evs if e.get('name') == nm]
        if not named:
            raise CliError(f"Invalid name: {nm}")
        matches = [e for e in named if event_signature(e) == query]
        if len(matches) == 1:
            return matches[0]
        # Match the common ethabi error for an event signature not matching the provided log.
        raise CliError(f"Invalid signature `0x{short_hash(query)}`")
    named = [e for e in evs if e.get('name') == query]
    if not named:
        raise CliError(f"Invalid name: {query}")
    if len(named) > 1:
        raise CliError(f"More than one function found for name `{query}`, try providing the full signature")
    return named[0]

def short_hash(sig: str) -> str:
    h = keccak256(sig.encode()).hex()
    return h[:4] + '…' + h[-4:]

# -------------------------- command implementations --------------------------
def semantic_error(e: Exception, encode_context: bool=False) -> int:
    if isinstance(e, HexError):
        if encode_context:
            print(f"Error: Hex parsing error: {e.msg}\n\nCaused by:\n    {e.msg}", file=sys.stderr)
        else:
            print(f"Error: {e.msg}", file=sys.stderr)
    elif isinstance(e, UintParseError):
        print(f"Error: Uint parse error: {e.kind}", file=sys.stderr)
    elif isinstance(e, InvalidData):
        print("Error: Invalid data", file=sys.stderr)
    elif isinstance(e, CliError):
        print(f"Error: {e}", file=sys.stderr)
    elif isinstance(e, FileNotFoundError):
        print(f"Error: {e}", file=sys.stderr)
    elif isinstance(e, json.JSONDecodeError):
        print(f"Error: {e}", file=sys.stderr)
    else:
        print(f"Error: {e}", file=sys.stderr)
    return 1

def clap_error(msg: str, usage: str) -> int:
    print(f"error: {msg}\n\nUSAGE:\n    {usage}\n\nFor more information try --help", file=sys.stderr)
    return 1

def parse_encode_params_args(args: List[str]):
    lenient = False
    pairs = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-h', '--help'):
            print(ENCODE_PARAMS_HELP_LONG, end='')
            return None
        if a in ('-V', '--version'):
            print(VERSION)
            return None
        if a in ('-l', '--lenient'):
            lenient = True; i += 1; continue
        if a == '-v':
            if i + 1 >= len(args):
                clap_error("The argument '-v <type-or-param> <type-or-param>' requires a value but none was supplied", f"{PROG} encode params -v <type-or-param> <type-or-param>")
                return None
            if i + 2 >= len(args):
                clap_error("The argument '-v <type-or-param> <type-or-param>' requires 2 values, but 1 was provided", f"{PROG} encode params -v <type-or-param> <type-or-param>")
                return None
            pairs.append((args[i+1], args[i+2])); i += 3; continue
        if a.startswith('-'):
            clap_error(f"Found argument '{a}' which wasn't expected, or isn't valid in this context", f"{PROG} encode params [FLAGS] [OPTIONS]")
            return None
        clap_error(f"Found argument '{a}' which wasn't expected, or isn't valid in this context", f"{PROG} encode params -v <type-or-param> <type-or-param>")
        return None
    return lenient, pairs

def cmd_encode_params(args: List[str]) -> int:
    parsed = parse_encode_params_args(args)
    if parsed is None:
        return 0 if any(a in ('-h','--help','-V','--version') for a in args) else 1
    lenient, pairs = parsed
    try:
        types = [parse_type(t) for t, _ in pairs]
        vals = [parse_value(t, v, lenient) for t, (_, v) in zip(types, pairs)]
        print(encode_params(types, vals).hex())
        return 0
    except Exception as e:
        return semantic_error(e, encode_context=True)

def parse_function_args(args: List[str], encode: bool):
    lenient = False
    params = []
    positionals = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-h', '--help'):
            print(ENCODE_FUNCTION_HELP if encode else DECODE_FUNCTION_HELP, end='')
            return None
        if a in ('-V', '--version'):
            print(VERSION); return None
        if encode and a in ('-l', '--lenient'):
            lenient = True; i += 1; continue
        if encode and a == '-p':
            if i + 1 >= len(args):
                clap_error("The argument '-p <params>...' requires a value but none was supplied", f"{PROG} encode function <abi-path> <function-name-or-signature> -p <params>...")
                return None
            params.append(args[i+1]); i += 2; continue
        if a.startswith('-') and not (encode and a.startswith('-') and a not in ('-p','-l','--lenient')):
            # negative values only occur after -p and were already consumed
            pass
        positionals.append(a); i += 1
    need = 2 if encode else 3
    if len(positionals) < need:
        if encode:
            clap_error("The following required arguments were not provided:\n    <abi-path>\n    <function-name-or-signature>", f"{PROG} encode function [FLAGS] [OPTIONS] <abi-path> <function-name-or-signature>")
        else:
            clap_error("The following required arguments were not provided:\n    <abi-path>\n    <function-name-or-signature>\n    <data>", f"{PROG} decode function <abi-path> <function-name-or-signature> <data>")
        return None
    if len(positionals) > need:
        clap_error(f"Found argument '{positionals[need]}' which wasn't expected, or isn't valid in this context", (f"{PROG} encode function <abi-path> <function-name-or-signature> -p <params>..." if encode else f"{PROG} decode function <abi-path> <function-name-or-signature> <data>"))
        return None
    return (lenient, params, positionals) if encode else positionals

def cmd_encode_function(args: List[str]) -> int:
    parsed = parse_function_args(args, True)
    if parsed is None:
        return 0 if any(a in ('-h','--help','-V','--version') for a in args) else 1
    lenient, params, pos = parsed
    try:
        abi = load_abi(pos[0])
        f = select_function(abi, pos[1])
        types = func_inputs(f)
        if len(params) < len(types):
            raise InvalidData()
        vals = [parse_value(t, params[i], lenient) for i, t in enumerate(types)]
        out = function_selector(f) + encode_params(types, vals)
        print(out.hex())
        return 0
    except Exception as e:
        return semantic_error(e, encode_context=True)

def parse_decode_params_args(args: List[str]):
    types = []
    data = None
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-h', '--help'):
            print(DECODE_PARAMS_HELP, end=''); return None
        if a in ('-V', '--version'):
            print(VERSION); return None
        if a == '-t':
            if i + 1 >= len(args):
                clap_error("The argument '-t <type>...' requires a value but none was supplied", f"{PROG} decode params [OPTIONS] <data>")
                return None
            types.append(args[i+1]); i += 2; continue
        if data is None:
            data = a; i += 1; continue
        if a == '-t':
            continue
        clap_error(f"Found argument '{a}' which wasn't expected, or isn't valid in this context", f"{PROG} decode params [OPTIONS] <data>")
        return None
    if data is None:
        print(f"error: The following required arguments were not provided:\n    <data>\n\nUSAGE:\n    {PROG} decode params [OPTIONS] <data>\n\nFor more information try --help", file=sys.stderr)
        return None
    return types, data

def cmd_decode_params(args: List[str]) -> int:
    parsed = parse_decode_params_args(args)
    if parsed is None:
        return 0 if any(a in ('-h','--help','-V','--version') for a in args) else 1
    type_strs, data_arg = parsed
    try:
        data = decode_hex_arg(data_arg)
        types = [parse_type(t) for t in type_strs]
        vals = decode_tuple(types, data, 0)
        for t, v in zip(types, vals):
            print(f"{t.canonical()} {display_value(t, v)}")
        if not types:
            print("")
        return 0
    except Exception as e:
        return semantic_error(e, encode_context=False)

def cmd_decode_function(args: List[str]) -> int:
    parsed = parse_function_args(args, False)
    if parsed is None:
        return 0 if any(a in ('-h','--help','-V','--version') for a in args) else 1
    try:
        abi = load_abi(parsed[0])
        f = select_function(abi, parsed[1])
        data = decode_hex_arg(parsed[2])
        types = func_outputs(f)
        vals = decode_tuple(types, data, 0)
        for t, v in zip(types, vals):
            print(f"{t.canonical()} {display_value(t, v)}")
        if not types:
            print("")
        return 0
    except Exception as e:
        return semantic_error(e, encode_context=False)

def parse_log_args(args: List[str]):
    topics = []
    positionals = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-h','--help'):
            print(DECODE_LOG_HELP, end=''); return None
        if a in ('-V','--version'):
            print(VERSION); return None
        if a == '-l':
            if i + 1 >= len(args):
                clap_error("The argument '-l <topic>...' requires a value but none was supplied", f"{PROG} decode log [OPTIONS] <abi-path> <event-name-or-signature> <data>")
                return None
            topics.append(args[i+1]); i += 2; continue
        positionals.append(a); i += 1
    if len(positionals) < 3:
        clap_error("The following required arguments were not provided:\n    <abi-path>\n    <event-name-or-signature>\n    <data>", f"{PROG} decode log [OPTIONS] <abi-path> <event-name-or-signature> <data>")
        return None
    if len(positionals) > 3:
        clap_error(f"Found argument '{positionals[3]}' which wasn't expected, or isn't valid in this context", f"{PROG} decode log [OPTIONS] <abi-path> <event-name-or-signature> <data>")
        return None
    return topics, positionals

def cmd_decode_log(args: List[str]) -> int:
    parsed = parse_log_args(args)
    if parsed is None:
        return 0 if any(a in ('-h','--help','-V','--version') for a in args) else 1
    topic_args, pos = parsed
    try:
        abi = load_abi(pos[0])
        e = select_event(abi, pos[1])
        topics = [parse_hex_bytes(x, allow_0x=False) for x in topic_args]
        for tp in topics:
            if len(tp) != 32: raise InvalidData()
        data = decode_hex_arg(pos[2])
        if not bool(e.get('anonymous', False)):
            if len(topics) < 1 or topics[0] != event_topic0(e):
                raise InvalidData()
            idx_topics = topics[1:]
        else:
            idx_topics = topics
        inputs = e.get('inputs') or []
        indexed = [p for p in inputs if p.get('indexed')]
        nonindexed = [p for p in inputs if not p.get('indexed')]
        if len(idx_topics) != len(indexed):
            raise InvalidData()
        non_types = [type_from_abi_param(p) for p in nonindexed]
        non_vals = decode_tuple(non_types, data, 0)
        non_iter = iter(non_vals)
        idx_iter = iter(idx_topics)
        out_vals = []
        for p in inputs:
            t = type_from_abi_param(p)
            if p.get('indexed'):
                raw = next(idx_iter)
                if t.is_dynamic():
                    val = raw
                    # display as bytes32-like hash regardless of original dynamic type
                    disp = raw.hex()
                else:
                    val = decode_value(t, raw, 0)
                    disp = display_value(t, val)
            else:
                val = next(non_iter)
                disp = display_value(t, val)
            out_vals.append((p.get('name',''), disp))
        for name, disp in out_vals:
            print(f"{name} {disp}")
        if not out_vals:
            print("")
        return 0
    except Exception as e:
        return semantic_error(e, encode_context=False)

# -------------------------- dispatch --------------------------
def main(argv: List[str]) -> int:
    if not argv:
        print(TOP_HELP, end='', file=sys.stderr)
        return 1
    if argv[0] in ('-h', '--help'):
        print(TOP_HELP, end='')
        return 0
    if argv[0] in ('-V', '--version'):
        print(VERSION)
        return 0
    if argv[0] == 'help':
        rest = argv[1:]
        if not rest:
            print(TOP_HELP, end=''); return 0
        if rest[0] == 'encode':
            if len(rest) == 1:
                print(ENCODE_HELP, end=''); return 0
            if rest[1] == 'params': print(ENCODE_PARAMS_HELP_SHORT, end=''); return 0
            if rest[1] == 'function': print(ENCODE_FUNCTION_HELP, end=''); return 0
        if rest[0] == 'decode':
            if len(rest) == 1:
                print(DECODE_HELP, end=''); return 0
            if rest[1] == 'params': print(DECODE_PARAMS_HELP, end=''); return 0
            if rest[1] == 'function': print(DECODE_FUNCTION_HELP, end=''); return 0
            if rest[1] == 'log': print(DECODE_LOG_HELP, end=''); return 0
        print(TOP_HELP, end='')
        return 0
    if argv[0] == 'encode':
        if len(argv) == 1:
            print(ENCODE_HELP, end='', file=sys.stderr); return 1
        if argv[1] in ('-h','--help'):
            print(ENCODE_HELP, end=''); return 0
        if argv[1] in ('-V','--version'):
            print(VERSION); return 0
        if argv[1] == 'help':
            if len(argv) == 2: print(ENCODE_HELP, end=''); return 0
            if argv[2] == 'params': print(ENCODE_PARAMS_HELP_SHORT, end=''); return 0
            if argv[2] == 'function': print(ENCODE_FUNCTION_HELP, end=''); return 0
        if argv[1] == 'params': return cmd_encode_params(argv[2:])
        if argv[1] == 'function': return cmd_encode_function(argv[2:])
        return clap_error(f"The subcommand '{argv[1]}' wasn't recognized", f"{PROG} encode <SUBCOMMAND>")
    if argv[0] == 'decode':
        if len(argv) == 1:
            print(DECODE_HELP, end='', file=sys.stderr); return 1
        if argv[1] in ('-h','--help'):
            print(DECODE_HELP, end=''); return 0
        if argv[1] in ('-V','--version'):
            print(VERSION); return 0
        if argv[1] == 'help':
            if len(argv) == 2: print(DECODE_HELP, end=''); return 0
            if argv[2] == 'params': print(DECODE_PARAMS_HELP, end=''); return 0
            if argv[2] == 'function': print(DECODE_FUNCTION_HELP, end=''); return 0
            if argv[2] == 'log': print(DECODE_LOG_HELP, end=''); return 0
        if argv[1] == 'params': return cmd_decode_params(argv[2:])
        if argv[1] == 'function': return cmd_decode_function(argv[2:])
        if argv[1] == 'log': return cmd_decode_log(argv[2:])
        return clap_error(f"The subcommand '{argv[1]}' wasn't recognized", f"{PROG} decode <SUBCOMMAND>")
    return clap_error(f"The subcommand '{argv[0]}' wasn't recognized", f"{PROG} <SUBCOMMAND>")

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
